def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_complete(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def main() -> int:
    print("=" * 40)
    print(" ORR-010 INSTALLER")
    print(" AUTHORIZATION CONSUMPTION")
    print("=" * 40)
    try:
        source_text = SOURCE.read_text(encoding="utf-8")
        required = (
            'SCHEMA_VERSION = "ORR-009"',
            "OracleResearchResponseEvidenceReadInvocationAuthorization",
            "authorization_hash",
            "authorized_invocation_ids",
            "authorized_invocation_hashes",
            "authorized_read_operations",
            "AUTHORIZATION_TYPE",
            "AUTHORIZATION_STATUS",
        )
        missing = [item for item in required if item not in source_text]
        if missing:
            raise RuntimeError(f"ORR-009 contract incomplete: {missing}")
        ast.parse(source_text, filename=str(SOURCE))
        protected_hash = sha256(SOURCE)
        print("[OK] Actual ORR-009 read-invocation authorization gate verified")

        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = (
            "from .oracle_research_response_evidence_read_invocation_authorization_consumption_gate import ("
            "CONSUMPTION_STATUS, "
            "CONSUMPTION_TYPE, "
            "OracleResearchResponseEvidenceReadInvocationAuthorizationConsumption, "
            "OracleResearchResponseEvidenceReadInvocationAuthorizationConsumptionGate, "
            "OracleResearchResponseEvidenceReadInvocationAuthorizationConsumptionInvariantError)"
        )
        current = (
            INIT.read_text(encoding="utf-8")
            if INIT.exists()
            else "from __future__ import annotations\n"
        )
        if export not in current:
            INIT.write_text(
                current.rstrip() + "\n\n" + export + "\n",
                encoding="utf-8",
                newline="\n",
            )
        ast.parse(INIT.read_text(encoding="utf-8"), filename=str(INIT))
        print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")

        completed = subprocess.run([sys.executable, str(TEST)], cwd=ROOT, check=False)
        if completed.returncode:
            raise RuntimeError(f"ORR-010 test failed with exit code {completed.returncode}")
        if sha256(SOURCE) != protected_hash:
            raise RuntimeError("Protected ORR-009 module changed")

        print("[PASS] Protected ORR-009 module unchanged")
        print("[PASS] ORR-001 through ORR-009 lineage preserved")
        print("[PASS] Authorization-consumption boundary established")
        print("[PASS] No callable was bound or invoked")
        print("[PASS] No acquisition, analytics, integration, operator, or runtime module modified")
        print("[PASS] No Q Series execution module modified")
        print(f"[PASS] Repository located: {ROOT}")
        print("[DONE] ORR-010 INSTALLED AND VERIFIED")
        return 0
    except (RuntimeError, SyntaxError, OSError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
